"use strict";(globalThis.webpackChunkgrc||=[]).push([[42992],{61335(e){e.exports=JSON.parse('{"citeKey":"yildirim2023iomax","slug":"yildirim-2023-iomax-3919","title":"IOMax: Maximizing Out-of-Core I/O Analysis Performance on HPC Systems","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Parallel Data Systems Workshop (PDSW\'23)","type":"Workshop","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3624062.3624191","abstract":"I/O analysis is an essential task for improving the performance of scientific applications on high-performance computing (HPC) systems. However, current analysis tools, which often use data drilling techniques (iterative exploration for deeper insights), treat every query independently and do not optimize column data for data-slicing (extracting specific data subsets), resulting in subpar querying performance. In this paper, we designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces. IOMax utilizes a novel query optimization technique to improve the query performance by 8.6x while reducing the memory footprint required for analysis by 11x. Additionally, it employs data transformation techniques to improve data-slicing performance by up to 11.4x. In conclusion, IOMax optimizes I/O analysis for scientific workflows on the Lassen supercomputer, resulting in up to 7x improvement.","hasAbstract":true,"lede":"We designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces.","links":{"pdf":"https://grc.iit.edu/papers/2023/yildirim-2023-iomax-3919.pdf"},"tags":["I/O Analysis","Out-of-Core Analysis","Data Drilling","WisIO"],"_projectIds":["chronolog","hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","chronolog","hermes","wisio","iris"],"memberAuthors":["yildirim-izzet","devarajan-hariharan","kougkas-anthony","sun-xian-he","mohror-kathryn"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"},{"agency":"LLNL","award":"DE-AC52-07NA27344"}]}')}}]);